ruleSearch.bookList:
@js:
var doc = org.jsoup.Jsoup.parse(result);
if (doc.select('ol.book-ol.book-ol-normal').size() > 0) {
  java.setContent(result);
  java.getElement('ol.book-ol.book-ol-normal li.book-li');
} else {
  var n = doc.select('meta[property=og:novel:book_name]');
  var a = doc.select('meta[property=og:novel:author]');
  var i = doc.select('meta[property=og:description]');
  var c = doc.select('meta[property=og:image]');
  var k = doc.select('meta[property=og:novel:category]');
  var name = n.size() > 0 ? n.first().attr('content') : '';
  var author = a.size() > 0 ? a.first().attr('content') : '';
  var intro = i.size() > 0 ? i.first().attr('content') : '';
  var cover = c.size() > 0 ? c.first().attr('content') : '';
  var kind = k.size() > 0 ? k.first().attr('content') : '';
  var esc = function(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
  var card = '<li class="book-li"><a href="' + baseUrl + '"><div class="book-cover"><img data-src="' + esc(cover) + '"></div><h4 class="book-title">' + esc(name) + '</h4><p class="book-desc">' + esc(intro) + '</p><span class="book-author">作者' + esc(author) + '</span><span class="tag-small-group"><em class="tag-small">' + esc(kind) + '</em></span></a></li>';
  java.setContent(card);
  java.getElement('li.book-li');
}

